import{_ as i,l,o as e,c as s,v as r,p,x as t,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"GPU SIMT 与 warp","description":"","frontmatter":{"title":"GPU SIMT 与 warp","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-simt.md","filePath":"cs/gpu-simt.md","lastUpdated":1789023840000}'),h={name:"cs/gpu-simt.md"};function m(B,a,E,_,u,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="gpu-simt-与-warp" tabindex="-1">GPU SIMT 与 warp <a class="header-anchor" href="#gpu-simt-与-warp" aria-label="Permalink to &quot;GPU SIMT 与 warp&quot;">​</a></h1><div class="epigraph"><p>一组线程共享同一 PC、走同一条指令，数据各异；硬件用掩码关掉分岔的人，而不是给每人一套完整的乱序核。</p><footer>—— 据 Lindholm et al., NVIDIA Tesla: A Unified Graphics and Computing Architecture, IEEE Micro 2008 整理</footer></div><p><a href="/cs/vector-lanes">上一课</a> 的 lane 由一条向量指令驱动，程序员看见的是向量寄存器。图形与数据并行负载有成千上万个「小程序实例」。本课不重讲 Cray 链式。缺口是 <strong>SIMT：把 lane 包装成线程，warp（或 wavefront）共享 PC，用线程切换藏延迟。</strong> 不是 Transformer 的注意力实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>为每个像素/每个粒子做一套 <a href="/cs/ooo-rob">ROB</a> 面积不可接受。它们的控制流大体相同。缺口不是再加 CPU 核，而是<strong>单指令多线程：32/64 个线程一拍锁步执行同一 opcode，寄存器文件按线程号分行，遇到长延迟则换另一个就绪 warp。</strong></p><p><span class="marginnote">NVIDIA 称 warp，AMD 称 wavefront。Lindholm 等描述 Tesla 统一着色器：图形与计算共用 SIMT 核。这是微结构，不是 CUDA 教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SM / CU 上驻留多个 warp。每拍选一个就绪 warp 发射（可宽发射多条）。寄存器：物理堆按线程切片，无 CPU 那种重命名密度。记分牌跟踪该 warp 的依赖；切换 warp 隐藏 cache/纹理/DRAM 延迟——这是 <a href="/cs/dataflow-dae">DAE</a> 的线程版。</p>',8)),(e(),p(c,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W0%5B%22warp%200%20%E5%85%B1%E4%BA%AB%20PC%22%5D%20--%3E%20LANE%5B%22lane%20%C3%97%20%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20W1%5B%22warp%201%20%E5%B0%B1%E7%BB%AA%E7%AD%89%E5%BE%85%22%5D%20--%3E%20SEL%5B%22%E8%B0%83%E5%BA%A6%E9%80%89%20warp%22%5D%0A%20%20MISS%5B%22%E9%95%BF%E5%BB%B6%E8%BF%9F%22%5D%20--%3E%20SW%5B%22%E5%88%87%E5%88%B0%E5%85%B6%E4%BB%96%20warp%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/mlp-memory-parallelism">MLP</a> 来自大量 outstanding 线程，而不是单个 ROB。占用率：寄存器与共享存储限制同时驻留的 warp 数，切换不够则延迟暴露。与 CPU MIMD：每个 CPU 线程有独立 PC 与一致性协议；SIMT 线程默认不提供那种强独立控制流。下一课存储层次：共享存储、私有 L1、HBM。</p><p>分支下一课才发散；本课只钉「共享 PC + 切换」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CUDA 编程模型细则，不写注意力 kernel。不要把 SIMT 说成「很大的 AVX」。多 socket CPU 仍是 MIMD。存储层次下一课。</p><p>后课默认：GPU 核用 warp 调度藏延迟。程序员看见的 bank、shared memory 与合并，决定有效带宽。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SIMT：warp 共享 PC，lane 上跑不同线程数据，切 warp 藏延迟。</li><li>面积换大量轻量上下文，而不是每线程乱序核。</li><li>GPU 存储层次是下一课。</li><li>出处：Lindholm et al., <em>IEEE Micro</em>, 2008。</li></ul>',8))])}const T=i(h,[["render",m]]);export{f as __pageData,T as default};
